function trTree(r){if(!r||(!LANGEN&&!TRON))return;const w=document.createTreeWalker(r,NodeFilter.SHOW_TEXT|NodeFilter.SHOW_ELEMENT);let n=w.currentNode;do{trNode(n)}while((n=w.nextNode()))}
