function tplFill(){const k=$("#tk").value,t=S.tpl[k];$("#tf").innerHTML=`<div class="row"><div><label>اسم المنشأة</label><input id="t_org" placeholder="${S.name}" value="${t.org}" oninput="tplPrev()"></div><div><label>عنوان المستند</label><input id="t_title" placeholder="${TK[k]}" value="${t.title}" oninput="tplPrev()"></div></div><div class="row"><div><label>الترويسة (سطر إضافي)</label><input id="t_head" placeholder="العنوان - التليفون - الرقم الضريبي" value="${t.head}" oninput="tplPrev()"></div><div><label>التذييل</label><input id="t_foot" placeholder="شكرًا لتعاملكم معنا" value="${t.foot}" oninput="tplPrev()"></div></div><div class="row"><div><label>حجم الخط (px)</label><input id="t_fs" type="number" value="${t.fs}" oninput="tplPrev()"></div><div><label>الهوامش (مم)</label><input id="t_mg" type="number" value="${t.mg}" oninput="tplPrev()"></div><div><label>محاذاة الترويسة</label><select id="t_al" onchange="tplPrev()"><option value="c" ${t.al=="c"?"selected":""}>وسط</option><option value="s" ${t.al=="s"?"selected":""}>بداية السطر</option></select></div></div><label><input type="checkbox" id="t_logo" ${t.logo?"checked":""} onchange="tplPrev()"> إظهار الشعار</label> <label><input type="checkbox" id="t_bar" ${t.bar?"checked":""} onchange="tplPrev()"> خط أسفل الترويسة</label><div><b>الحقول المعروضة</b></div>${U(TCOL[k],c=>`<label style="display:block"><input type="checkbox" class="t_c" value="${c[0]}" ${t.hide.includes(c[0])?"":"checked"} onchange="tplPrev()"> ${c[1]}</label>`)||'<p class="mu">لا توجد حقول اختيارية لهذا المستند</p>'}<div class="row"><button onclick="tplSave()">حفظ القالب</button><button class="g" onclick="tplReset()">استعادة الافتراضي</button>${bk}</div>`;tplPrev()}
const tplRead=()=>({org:$("#t_org").value.trim(),title:$("#t_title").value.trim(),head:$("#t_head").value.trim(),foot:$("#t_foot").value.trim(),fs:+$("#t_fs").value||14,mg:+$("#t_mg").value||0,al:$("#t_al").value,logo:$("#t_logo").checked?1:0,bar:$("#t_bar").checked?1:0,hide:[...ACT.querySelectorAll(".t_c:not(:checked)")].map(x=>x.value)});
function tplPrev(){const k=$("#tk").value;TPO=tplRead();try{$("#tpv").innerHTML=sampleHtml(k)}finally{TPO=null}}
