function ppage(title,html,extra){sh(`<div class="ph"><h3>${title}</h3><div class="row"><button onclick="print()">🖨️ طباعة</button><button class="g" onclick="savePdf()">💾 حفظ PDF</button><button class="g" onclick="sharePdf()">📤 مشاركة ملف PDF</button>${extra||""}${bk}</div></div>${html}${WAI}`)}
